MERGE INTO ROLE_MODULE_ACCESS t USING (SELECT 'REVIEWER' role, 'REVIEW' module_code FROM dual) s ON (t.role = s.role AND t.module_code = s.module_code) WHEN NOT MATCHED THEN INSERT (role, module_code, enabled) VALUES (s.role, s.module_code, 'Y');
